import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type Job = {
  id: string; status: 'queued' | 'running' | 'completed' | 'failed'; input: string;
  steps: number; failAttempts: number; attempts: number;
  progress: { completed: number; total: number }; result: { output: string } | null;
  error: string | null; createdAt: string; updatedAt: string;
};

export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL, steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0, result_output TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL, idempotency_key TEXT UNIQUE,
      payload TEXT NOT NULL, available_at INTEGER NOT NULL DEFAULT 0,
      recovery INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_created ON jobs(created_at DESC);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK(id=1), at INTEGER NOT NULL);
  `);
  return db;
}

type Row = Record<string, unknown>;
export function toJob(row: Row): Job {
  const status = String(row.status) as Job['status'];
  return {
    id: String(row.id), status, input: String(row.input), steps: Number(row.steps),
    failAttempts: Number(row.fail_attempts), attempts: Number(row.attempts),
    progress: { completed: Number(row.progress_completed), total: Number(row.steps) },
    result: status === 'completed' ? { output: String(row.result_output ?? '') } : null,
    error: status === 'failed' ? String(row.error ?? '') : null,
    createdAt: String(row.created_at), updatedAt: String(row.updated_at),
  };
}

export function getJob(db: DatabaseSync, id: string): Job | null {
  const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Row | undefined;
  return row ? toJob(row) : null;
}

