import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, getJob, toJob, type Job } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
function invalidKeyField(key: string | undefined): {field:string;message:string}[] {
  return key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key)
    ? [{field:'Idempotency-Key',message:'must contain 1–128 letters, numbers, underscores, or hyphens'}] : [];
}
async function readBody(req: IncomingMessage): Promise<string> {
  let data = ''; for await (const chunk of req) { data += chunk.toString(); if (data.length > 1_000_000) throw new Error('too_large'); }
  return data;
}
function handleSubmit(res: ServerResponse, raw: string, key: string | undefined): void {
  let body: unknown;
  try { body = JSON.parse(raw); } catch { error(res, 400, 'invalid_request', 'Request body must be valid JSON.', [{field:'body',message:'must be valid JSON'}, ...invalidKeyField(key)]); return; }
  const fields: {field:string;message:string}[] = invalidKeyField(key);
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    error(res, 400, 'invalid_request', 'Request body must be an object.', [{field:'body',message:'must be an object'}, ...fields]); return;
  }
  const obj = body as Record<string, unknown>;
  for (const name of Object.keys(obj)) if (!['input','steps','failAttempts'].includes(name)) fields.push({field:name,message:'is not allowed'});
  if (!Object.hasOwn(obj, 'input')) fields.push({field:'input',message:'is required'});
  else if (typeof obj.input !== 'string') fields.push({field:'input',message:'must be a string'});
  else if (obj.input.length < 1 || obj.input.length > 1000 || obj.input.trim().length === 0) fields.push({field:'input',message:'must be 1–1000 characters and not only whitespace'});
  if (Object.hasOwn(obj, 'steps') && (!Number.isInteger(obj.steps) || (obj.steps as number) < 1 || (obj.steps as number) > 20)) fields.push({field:'steps',message:'must be an integer from 1 to 20'});
  if (Object.hasOwn(obj, 'failAttempts') && (!Number.isInteger(obj.failAttempts) || (obj.failAttempts as number) < 0 || (obj.failAttempts as number) > 5)) fields.push({field:'failAttempts',message:'must be an integer from 0 to 5'});
  if (fields.length) { error(res, 400, 'invalid_request', 'Request validation failed.', fields); return; }

  const input = obj.input as string, steps = (obj.steps ?? 5) as number, failAttempts = (obj.failAttempts ?? 0) as number;
  const payload = JSON.stringify({input, steps, failAttempts});
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const found = db.prepare('SELECT * FROM jobs WHERE idempotency_key=?').get(key) as Record<string, unknown> | undefined;
      if (found) {
        db.exec('COMMIT');
        if (found.payload === payload) send(res, 200, toJob(found));
        else error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        return;
      }
    }
    const id = randomUUID(), now = new Date().toISOString();
    db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,idempotency_key,payload)
      VALUES(?,?,?,?,?,0,0,?,?,?,?)`).run(id, 'queued', input, steps, failAttempts, now, now, key ?? null, payload);
    db.exec('COMMIT');
    const job = getJob(db, id) as Job;
    send(res, 201, job);
  } catch (e) { db.exec('ROLLBACK'); throw e; }
}

const known = (path: string) => path === '/' || path === '/health' || path === '/api/jobs' || /^\/api\/jobs\/[^/]+$/.test(path);
const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (!known(pathname)) return error(res, 404, 'not_found', 'Route not found.');
  if (pathname === '/' && req.method === 'GET') { res.writeHead(200, {'content-type':'text/html; charset=utf-8'}); res.end(uiHtml); return; }
  if (pathname === '/health' && req.method === 'GET') {
    const row = db.prepare('SELECT at FROM worker_heartbeat WHERE id=1').get() as {at:number}|undefined;
    return send(res, 200, {status:'ok',worker:row && Date.now()-row.at < 3000 ? 'up' : 'down'});
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const type = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(type)) return error(res,400,'invalid_request','Content-Type must be application/json.',[{field:'Content-Type',message:'must be application/json'}, ...invalidKeyField(typeof req.headers['idempotency-key'] === 'string' ? req.headers['idempotency-key'] : req.headers['idempotency-key']?.join(','))]);
    try { const header = req.headers['idempotency-key']; handleSubmit(res, await readBody(req), typeof header === 'string' ? header : header?.join(',')); }
    catch (e) { if (e instanceof Error && e.message === 'too_large') error(res,400,'invalid_request','Request body is too large.',[{field:'body',message:'is too large'}, ...invalidKeyField(typeof req.headers['idempotency-key'] === 'string' ? req.headers['idempotency-key'] : req.headers['idempotency-key']?.join(','))]); else error(res,500,'internal_error','Internal server error.'); }
    return;
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string,unknown>[];
    return send(res,200,{jobs:rows.map(toJob)});
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match && req.method === 'GET') {
    let id: string; try { id = decodeURIComponent(match[1]!); } catch { return error(res,404,'not_found','Job not found.'); }
    const job = getJob(db,id); return job ? send(res,200,job) : error(res,404,'not_found','Job not found.');
  }
  return error(res,405,'method_not_allowed','Method not allowed.');
});
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));

