import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });
// An interrupted attempt is retried as the same attempt after restart.
db.prepare("UPDATE jobs SET status='queued', recovery=1, available_at=0, updated_at=? WHERE status='running'").run(new Date().toISOString());

function heartbeat(): void {
  db.prepare('INSERT INTO worker_heartbeat(id,at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET at=excluded.at').run(Date.now());
}
function claim(): Record<string, unknown> | null {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC,rowid ASC LIMIT 1").get(Date.now()) as Record<string,unknown>|undefined;
    if (!row) { db.exec('COMMIT'); return null; }
    const attempts = Number(row.attempts) + (Number(row.recovery) ? 0 : 1);
    const now = new Date().toISOString();
    db.prepare("UPDATE jobs SET status='running',attempts=?,progress_completed=0,recovery=0,updated_at=? WHERE id=?").run(attempts,now,String(row.id));
    db.exec('COMMIT');
    return {...row, attempts};
  } catch (e) { db.exec('ROLLBACK'); throw e; }
}
async function processJob(job: Record<string,unknown>): Promise<void> {
  const id = String(job.id), steps = Number(job.steps), attempt = Number(job.attempts);
  const now = () => new Date().toISOString();
  if (attempt <= Number(job.fail_attempts)) {
    if (attempt >= 3) {
      db.prepare("UPDATE jobs SET status='failed',error='transient failure',result_output=NULL,updated_at=? WHERE id=?").run(now(),id);
    } else {
      db.prepare("UPDATE jobs SET status='queued',error=NULL,result_output=NULL,available_at=?,updated_at=? WHERE id=?").run(Date.now()+500,now(),id);
    }
    return;
  }
  for (let n=1;n<=steps;n++) {
    await sleep(100);
    if (stopping) return;
    db.prepare("UPDATE jobs SET progress_completed=?,updated_at=? WHERE id=? AND status='running'").run(n,now(),id);
  }
  db.prepare("UPDATE jobs SET status='completed',result_output=?,error=NULL,progress_completed=?,updated_at=? WHERE id=? AND status='running'").run(String(job.input).toUpperCase(),steps,now(),id);
}

console.log('worker started');
try {
  while (!stopping) {
    heartbeat();
    const job = claim();
    if (job) await processJob(job);
    else await sleep(100);
  }
} finally {
  db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run();
  db.close();
}

