9	    form{display:grid;gap:.8rem;padding:1rem;border:1px solid #ccd3df;border-radius:8px}
10	    label{display:grid;gap:.3rem}input,button{font:inherit;padding:.5rem}button{width:max-content;cursor:pointer}
11	    [role=alert]{color:#a21b1b;min-height:1.4em}.job{border-bottom:1px solid #ddd;padding:.8rem 0}.muted{color:#586174}
12	  </style>
13	</head>
14	<body>
15	  <h1>Job tracker</h1>
16	  <form data-testid="job-form">
17	    <label>Input <input data-testid="job-input" name="input" type="text" required maxlength="1000"></label>
18	    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
19	    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
20	    <button data-testid="job-submit" type="submit">Submit job</button>
21	    <div data-testid="form-error" role="alert"></div>
22	  </form>
23	  <h2>Jobs</h2>
24	  <div data-testid="job-list" aria-live="polite"></div>
25	  <script>
26	    const form=document.querySelector('[data-testid="job-form"]');
27	    const errorBox=document.querySelector('[data-testid="form-error"]');
28	    const list=document.querySelector('[data-testid="job-list"]');
29	    function render(jobs){
30	      list.replaceChildren();
31	      for(const job of jobs){
32	        const item=document.createElement('article'); item.className='job'; item.dataset.testid='job-item'; item.dataset.jobId=job.id;
33	        const title=document.createElement('strong'); title.textContent=job.input; item.append(title,document.createTextNode(' — '));
34	        const status=document.createElement('span'); status.dataset.testid='job-status'; status.textContent=job.status; item.append(status,document.createTextNode(' · '));
35	        const progress=document.createElement('span'); progress.dataset.testid='job-progress'; progress.textContent=`${job.progress.completed}/${job.progress.total}`; item.append(progress);
36	        const output=document.createElement('div'); output.dataset.testid='job-result'; output.textContent=job.result?.output ?? job.error ?? ''; item.append(output);
37	        const meta=document.createElement('small'); meta.className='muted'; meta.textContent=`Attempts: ${job.attempts}`; item.append(meta);
38	        list.append(item);
39	      }
40	    }
41	    async function refresh(){
42	      try{const response=await fetch('/api/jobs'); if(response.ok){const data=await response.json();render(data.jobs)}}catch{}
43	    }
44	    form.addEventListener('submit',async event=>{
45	      event.preventDefault(); errorBox.textContent='';
46	      const payload={input:form.elements.input.value,steps:Number(form.elements.steps.value),failAttempts:Number(form.elements.failAttempts.value)};
47	      try{
48	        const response=await fetch('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
49	        const data=await response.json();
50	        if(!response.ok){const details=data.error?.fields?.map(f=>`${f.field}: ${f.message}`).join('; ');errorBox.textContent=details?`${data.error.message} ${details}`:data.error?.message??'Submission failed.'}
51	        else{form.elements.input.value='';await refresh()}
52	      }catch{errorBox.textContent='Could not submit job.'}
53	    });
54	    refresh(); setInterval(refresh,700);
55	  </script>
56	</body>
57	</html>
